// Rider 5.4a: skinned UE5 Manny (web-ready by SketchPunk, CC BY 4.0 — licence for commercial use still to be
// confirmed, see docs/ASSETS.md) on the Innerscene snowboard (CC0). Assets come from the motionbricks project and are
// shrunk by scripts/optimize-rider-assets.mjs into public/assets/rider/.
//
// Driving: the same pose solver as rider v1 (pose.ts, fed with Manny's measured bone lengths, the board's binding
// layout and the relaxed motionbricks arm tuning) gives joint targets every frame; each Manny bone is then aimed at
// its target ("frame retarget": rest bone direction + bend side → target direction + bend side), legs and arms are
// re-solved with two-bone IK from Manny's actual hip / shoulder so feet stay exactly on the bindings.
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import type { Vec3 } from '../core/contracts';
import { twoBoneIK } from './ik';
import { DIMS, type Dims, type Pose } from './pose';
import { RiderRig } from './rider';

/** Manny bones we drive or measure (UE names; files may append `_<n>`, e.g. Sketchfab's `pelvis_78`). */
export const MANNY_BONES = {
  pelvis: 'pelvis',
  spine1: 'spine_01', spine2: 'spine_02', spine3: 'spine_03', spine4: 'spine_04', spine5: 'spine_05',
  neck1: 'neck_01', neck2: 'neck_02', head: 'head',
  upperarmL: 'upperarm_l', lowerarmL: 'lowerarm_l', handL: 'hand_l',
  upperarmR: 'upperarm_r', lowerarmR: 'lowerarm_r', handR: 'hand_r',
  thighL: 'thigh_l', calfL: 'calf_l', footL: 'foot_l', ballL: 'ball_l',
  thighR: 'thigh_r', calfR: 'calf_r', footR: 'foot_r', ballR: 'ball_r',
} as const;
export type MannyBone = keyof typeof MANNY_BONES;
/** Optional bones (F3: shoulders shrug / protract through the clavicles when present). */
export const MANNY_OPTIONAL_BONES = { clavL: 'clavicle_l', clavR: 'clavicle_r' } as const;
type OptBone = keyof typeof MANNY_OPTIONAL_BONES;

/** Does node name `actual` stand for bone `wanted`? Exact or `wanted_<digits>`, case-insensitive. */
export function isBoneName(wanted: string, actual: string): boolean {
  const a = actual.toLowerCase(), w = wanted.toLowerCase();
  return a === w || (a.startsWith(w + '_') && /^\d+$/.test(a.slice(w.length + 1)));
}

/** Map wanted bone keys → actual node names (first match wins). */
export function mapBoneNames<K extends string>(names: readonly string[], want: Readonly<Record<K, string>>): { map: Partial<Record<K, string>>; missing: K[] } {
  const map: Partial<Record<K, string>> = {};
  const missing: K[] = [];
  for (const k of Object.keys(want) as K[]) {
    const hit = names.find((n) => isBoneName(want[k], n));
    if (hit) map[k] = hit; else missing.push(k);
  }
  return { map, missing };
}

/**
 * Snowboard asset layout (snowboard.glb after a 180° turn about +y so the toe edge faces +z like the rider frame):
 * binding centres at x ≈ ±0.269, authored binding angles +15° (front) / −6° (back), boot floor ≈ 3.5 cm above the base.
 */
export const BOARD_ASSET = { stanceHalf: 0.269, authoredAngles: [15, -6] as const, floorY: 0.035, waist: 0.25 };
/** Stance used in game: ±15° duck (the back binding is re-angled at load). */
export const STANCE_ANGLES: readonly [number, number] = [15, -15];

/** Body / stance dims for the pose solver, from Manny's measured rest skeleton (model space, metres). */
export function mannyDims(m: {
  hipL: Vec3; hipR: Vec3; kneeL: Vec3; ankleL: Vec3; neck1: Vec3; head: Vec3;
  shoulderL: Vec3; shoulderR: Vec3; elbowL: Vec3; handL: Vec3;
}): Dims {
  const d = (a: Vec3, b: Vec3) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
  const hipY = (m.hipL[1] + m.hipR[1]) / 2;
  return {
    ...DIMS,
    boardWaist: BOARD_ASSET.waist,
    boardThick: BOARD_ASSET.floorY, // pose.ts: ankle = board base + boardThick + ankleH
    stanceHalf: BOARD_ASSET.stanceHalf, duckDeg: STANCE_ANGLES[0], duckBackDeg: STANCE_ANGLES[1],
    ankleH: m.ankleL[1], // rest model stands with the soles on y = 0
    footZ: -0.075, // heel against the highback, toes / heels overhang evenly (Manny foot ≈ 26 cm)
    balanceZ: 0.07, // stack the hips over mid-foot (≈ board centre line), not over the ankles
    thigh: d(m.hipL, m.kneeL), shin: d(m.kneeL, m.ankleL), hipHalf: Math.abs(m.hipL[0] - m.hipR[0]) / 2,
    spine: m.neck1[1] - hipY, neck: Math.max(0.05, m.head[1] - m.neck1[1] - 0.03),
    shoulderHalf: Math.abs(m.shoulderL[0] - m.shoulderR[0]) / 2,
    upperArm: d(m.shoulderL, m.elbowL), foreArm: d(m.elbowL, m.handL),
  };
}

const _m0 = new THREE.Matrix4(), _m1 = new THREE.Matrix4();
const _a = new THREE.Vector3(), _b = new THREE.Vector3(), _c = new THREE.Vector3(), _d = new THREE.Vector3(), _e = new THREE.Vector3(), _f = new THREE.Vector3();
/**
 * Rotation taking the orthonormal frame (a0, b0⊥a0) onto (a1, b1⊥a1): a0 → a1 exactly, b0 → b1 as close as the
 * constraint allows. Used to aim a bone (a = bone direction, b = bend / facing side). Pure (writes `out`).
 */
export function frameRotation(a0: THREE.Vector3, b0: THREE.Vector3, a1: THREE.Vector3, b1: THREE.Vector3, out = new THREE.Quaternion()): THREE.Quaternion {
  const basis = (a: THREE.Vector3, b: THREE.Vector3, x: THREE.Vector3, y: THREE.Vector3, z: THREE.Vector3, m: THREE.Matrix4) => {
    x.copy(a).normalize();
    y.copy(b).addScaledVector(x, -b.dot(x));
    if (y.lengthSq() < 1e-10) y.set(Math.abs(x.y) < 0.9 ? 0 : 1, Math.abs(x.y) < 0.9 ? 1 : 0, 0).addScaledVector(x, -(Math.abs(x.y) < 0.9 ? x.y : x.x));
    y.normalize();
    z.crossVectors(x, y);
    return m.makeBasis(x, y, z);
  };
  basis(a0, b0, _a, _b, _c, _m0);
  basis(a1, b1, _d, _e, _f, _m1);
  return out.setFromRotationMatrix(_m1.multiply(_m0.transpose()));
}

interface BoneRest { bone: THREE.Bone; q: THREE.Quaternion; p: THREE.Vector3; mq: THREE.Quaternion; mp: THREE.Vector3 }

const v = (a: Vec3) => new THREE.Vector3(a[0], a[1], a[2]);
const SPINE: MannyBone[] = ['spine1', 'spine2', 'spine3', 'spine4', 'spine5'];
const SPINE_W = [0.15, 0.35, 0.55, 0.8, 1];

export interface MannyAssets { manny: THREE.Group; board: THREE.Group }

export class MannyRider extends RiderRig {
  private model: THREE.Object3D;
  private board: THREE.Group;
  private rest = new Map<MannyBone, BoneRest>();
  private clav: (THREE.Bone | null)[] = [null, null];
  private clavRestQ: (THREE.Quaternion | null)[] = [null, null];
  private cacheQ = new Map<THREE.Object3D, THREE.Quaternion>();
  private cacheP = new Map<THREE.Object3D, THREE.Vector3>();
  private len: { upper: number; fore: number; thigh: number; shin: number };
  private restHipC = new THREE.Vector3();
  private footFwd0: THREE.Vector3[] = [];
  readonly triangles: number;

  constructor(assets: MannyAssets) {
    super();
    this.root.name = 'rider-manny';
    this.arms = 'natural';
    // motionbricks crouch (7–17 cm): v1 flex alone leaves Manny almost straight-legged at rest, but the full v1 range
    // reads as sitting on the snow in heelside brakes → lift the floor, compress the top
    this.flexBias = 0.12; this.flexScale = 0.82;
    this.model = assets.manny;
    this.board = new THREE.Group();
    this.board.add(prepareBoard(assets.board));
    this.root.add(this.board, this.model);
    let tris = 0;
    this.model.traverse((o) => {
      const m = o as THREE.SkinnedMesh;
      if (!m.isMesh) return;
      m.castShadow = true; m.receiveShadow = true;
      m.frustumCulled = false; // skinned bounds don't follow the pose; one character, always near the camera
      const mat = m.material as THREE.MeshStandardMaterial;
      mat.side = THREE.FrontSide; // the Sketchfab export is double-sided; closed mesh → half the fill / shadow cost
      mat.roughness = Math.max(mat.roughness, 0.55);
      tris += (m.geometry.index?.count ?? m.geometry.getAttribute('position').count) / 3;
    });
    this.triangles = tris;
    // bones
    const bones: THREE.Bone[] = [];
    this.model.traverse((o) => { if ((o as THREE.Bone).isBone) bones.push(o as THREE.Bone); });
    const { map, missing } = mapBoneNames(bones.map((b) => b.name), MANNY_BONES);
    if (missing.length) throw new Error(`Manny: missing bones ${missing.join(', ')}`);
    this.model.updateMatrixWorld(true);
    const inv = new THREE.Matrix4().copy(this.model.matrixWorld).invert();
    for (const k of Object.keys(MANNY_BONES) as MannyBone[]) {
      const bone = bones.find((b) => b.name === map[k])!;
      const mm = new THREE.Matrix4().multiplyMatrices(inv, bone.matrixWorld);
      const mp = new THREE.Vector3(), mq = new THREE.Quaternion(), ms = new THREE.Vector3();
      mm.decompose(mp, mq, ms);
      this.rest.set(k, { bone, q: bone.quaternion.clone(), p: bone.position.clone(), mq, mp });
    }
    const opt = mapBoneNames(bones.map((b) => b.name), MANNY_OPTIONAL_BONES).map;
    this.clav = (['clavL', 'clavR'] as OptBone[]).map((k) => bones.find((b) => b.name === opt[k]) ?? null);
    this.clavRestQ = this.clav.map((b) => b?.quaternion.clone() ?? null);
    const P = (k: MannyBone) => this.rest.get(k)!.mp;
    const arr = (k: MannyBone): Vec3 => [P(k).x, P(k).y, P(k).z];
    this.dims = mannyDims({
      hipL: arr('thighL'), hipR: arr('thighR'), kneeL: arr('calfL'), ankleL: arr('footL'), neck1: arr('neck1'), head: arr('head'),
      shoulderL: arr('upperarmL'), shoulderR: arr('upperarmR'), elbowL: arr('lowerarmL'), handL: arr('handL'),
    });
    this.len = {
      upper: P('upperarmL').distanceTo(P('lowerarmL')), fore: P('lowerarmL').distanceTo(P('handL')),
      thigh: P('thighL').distanceTo(P('calfL')), shin: P('calfL').distanceTo(P('footL')),
    };
    this.restHipC.copy(P('thighL')).add(P('thighR')).multiplyScalar(0.5);
    for (const [f, b] of [['footL', 'ballL'], ['footR', 'ballR']] as const) {
      const d = P(b).clone().sub(P(f)); d.y = 0; this.footFwd0.push(d.normalize());
    }
  }

  // ---- model-space transforms (model root = rider frame) ----
  private mq(o: THREE.Object3D): THREE.Quaternion {
    const c = this.cacheQ.get(o);
    if (c) return c;
    const q = o === this.model || !o.parent ? new THREE.Quaternion() : this.mq(o.parent).clone().multiply(o.quaternion);
    this.cacheQ.set(o, q);
    return q;
  }
  private mp(o: THREE.Object3D): THREE.Vector3 {
    const c = this.cacheP.get(o);
    if (c) return c;
    const p = o === this.model || !o.parent ? new THREE.Vector3() : o.position.clone().applyQuaternion(this.mq(o.parent)).add(this.mp(o.parent)); // armature has unit scale
    this.cacheP.set(o, p);
    return p;
  }
  /** Set bone `k` to model-space rotation `q` (and optionally model-space position `p`). */
  private setModel(k: MannyBone, q: THREE.Quaternion, p?: THREE.Vector3) {
    const b = this.rest.get(k)!.bone;
    const pq = this.mq(b.parent!);
    const ipq = pq.clone().invert();
    b.quaternion.copy(ipq).multiply(q);
    this.cacheQ.set(b, q.clone());
    if (p) {
      b.position.copy(p).sub(this.mp(b.parent!)).applyQuaternion(ipq);
      this.cacheP.set(b, p.clone());
    } else this.cacheP.delete(b);
  }
  /** Aim bone k: rest direction (k → child) maps to `dir`, rest side `side0` maps to `side`. */
  private aim(k: MannyBone, child: MannyBone, side0: THREE.Vector3, dir: THREE.Vector3, side: THREE.Vector3) {
    const r = this.rest.get(k)!, c = this.rest.get(child)!;
    const d0 = c.mp.clone().sub(r.mp);
    const q = frameRotation(d0, side0, dir, side).multiply(r.mq);
    this.setModel(k, q);
  }

  apply(p: Pose) {
    this.board.position.set(p.boardPos[0], p.boardPos[1], p.boardPos[2]);
    this.board.rotation.set(p.boardEdge, 0, 0);
    this.cacheQ.clear(); this.cacheP.clear();
    this.clav.forEach((b, i) => { if (b) b.quaternion.copy(this.clavRestQ[i]!); });
    const UP = new THREE.Vector3(0, 1, 0), RIGHT = new THREE.Vector3(1, 0, 0), FWD = new THREE.Vector3(0, 0, 1);
    // pelvis: up = body axis, side = hip line; place so the hip centre lands on the solved pelvis point
    const hipAxis = v(p.hip[0]).sub(v(p.hip[1]));
    const qPel = frameRotation(UP, RIGHT, v(p.bodyUp), hipAxis);
    const rp = this.rest.get('pelvis')!;
    const pelPos = v(p.pelvis).sub(this.restHipC.clone().sub(rp.mp).applyQuaternion(qPel));
    this.setModel('pelvis', qPel.clone().multiply(rp.mq), pelPos);
    // spine: blend pelvis → chest frame (up = torso axis, side = shoulder line)
    const shAxis = v(p.shoulder[0]).sub(v(p.shoulder[1]));
    const qChest = frameRotation(UP, RIGHT, v(p.torsoUp), shAxis);
    SPINE.forEach((k, i) => this.setModel(k, qPel.clone().slerp(qChest, SPINE_W[i]).multiply(this.rest.get(k)!.mq)));
    // neck + head: look along headFwd, up = neck → head
    const headUp = v(p.head).sub(v(p.neck));
    const qHead = frameRotation(UP, FWD, headUp, v(p.headFwd));
    (['neck1', 'neck2', 'head'] as const).forEach((k, i) => this.setModel(k, qChest.clone().slerp(qHead, [0.35, 0.65, 1][i]).multiply(this.rest.get(k)!.mq)));
    // arms: keep the solved hand offset from the shoulder, re-solve IK from Manny's own shoulder
    const ARMS = [['upperarmL', 'lowerarmL', 'handL'], ['upperarmR', 'lowerarmR', 'handR']] as const;
    // shoulders: swing the clavicle so the upper-arm head follows the solved shoulder shift (F3)
    for (let i = 0; i < 2; i++) {
      const cb = this.clav[i], sh = p.shoulderShift?.[i];
      if (!cb || !sh || (sh[0] === 0 && sh[1] === 0 && sh[2] === 0)) continue;
      const ub = this.rest.get(ARMS[i][0])!.bone;
      if (ub.parent !== cb) continue;
      const C = this.mp(cb), S0 = this.mp(ub).clone();
      const d0 = S0.clone().sub(C), d1 = S0.clone().add(v(sh)).sub(C);
      const q = new THREE.Quaternion().setFromUnitVectors(d0.normalize(), d1.normalize()).multiply(this.mq(cb));
      const pq = this.mq(cb.parent!).clone().invert();
      cb.quaternion.copy(pq).multiply(q);
      this.cacheQ.set(cb, q.clone());
      for (const k of ARMS[i]) { const b = this.rest.get(k)!.bone; this.cacheQ.delete(b); this.cacheP.delete(b); }
    }
    for (let i = 0; i < 2; i++) {
      const [u, l, h] = ARMS[i];
      const S = this.mp(this.rest.get(u)!.bone).clone();
      const tgt = S.clone().add(v(p.hand[i]).sub(v(p.shoulder[i])));
      const pole = v(p.elbow[i]).sub(v(p.shoulder[i]).add(v(p.hand[i])).multiplyScalar(0.5));
      const ik = twoBoneIK([S.x, S.y, S.z], [tgt.x, tgt.y, tgt.z], this.len.upper, this.len.fore, [pole.x, pole.y, pole.z]);
      const E = v(ik.mid), H = v(ik.end);
      const bend = bendDir(S, E, H, pole);
      const side0 = new THREE.Vector3(0, 0, -1); // rest elbows point backwards
      this.aim(u, l, side0, E.clone().sub(S), bend);
      this.aim(l, h, side0, H.clone().sub(E), bend);
    }
    // legs: IK from Manny's hip to the locked ankle; feet flat on the binding, toes along the binding angle
    const LEGS = [['thighL', 'calfL', 'footL', 'ballL'], ['thighR', 'calfR', 'footR', 'ballR']] as const;
    const boardUp = new THREE.Vector3(0, 1, 0).applyAxisAngle(RIGHT, p.boardEdge);
    for (let i = 0; i < 2; i++) {
      const [t, c, f] = LEGS[i];
      const Hp = this.mp(this.rest.get(t)!.bone).clone();
      const A = v(p.ankle[i]);
      const pole = v(p.knee[i]).sub(v(p.hip[i]).add(A).multiplyScalar(0.5));
      const ik = twoBoneIK([Hp.x, Hp.y, Hp.z], [A.x, A.y, A.z], this.len.thigh, this.len.shin, [pole.x, pole.y, pole.z]);
      const K = v(ik.mid), An = v(ik.end);
      const bend = bendDir(Hp, K, An, pole);
      this.aim(t, c, FWD, K.clone().sub(Hp), bend);
      this.aim(c, f, FWD, An.clone().sub(K), bend);
      const qFoot = frameRotation(UP, this.footFwd0[i], boardUp, v(p.footDir[i]));
      this.setModel(f, qFoot.multiply(this.rest.get(f)!.mq));
    }
  }
}

/** Unit vector from the root→end line toward the middle joint (falls back to the pole when straight). */
function bendDir(a: THREE.Vector3, m: THREE.Vector3, e: THREE.Vector3, pole: THREE.Vector3): THREE.Vector3 {
  const ax = e.clone().sub(a).normalize();
  const b = m.clone().sub(a);
  b.addScaledVector(ax, -b.dot(ax));
  if (b.lengthSq() < 1e-8) { b.copy(pole).addScaledVector(ax, -pole.dot(ax)); }
  return b.normalize();
}

/**
 * Snowboard + bindings: turn the asset so the toe edge faces +z, then re-angle the back binding from its authored
 * angle to STANCE_ANGLES (split by side, rotate about the binding centre).
 */
function prepareBoard(src: THREE.Group): THREE.Group {
  const g = new THREE.Group();
  g.add(src);
  src.updateMatrixWorld(true);
  const delta = THREE.MathUtils.degToRad(STANCE_ANGLES[1] - BOARD_ASSET.authoredAngles[1]);
  const meshes: THREE.Mesh[] = [];
  src.traverse((o) => { if ((o as THREE.Mesh).isMesh) meshes.push(o as THREE.Mesh); });
  const toSrc = new THREE.Matrix4().copy(src.matrixWorld).invert();
  for (const m of meshes) {
    m.castShadow = true; m.receiveShadow = true;
    const isBinding = /binding/i.test(m.name + ' ' + (m.parent?.name ?? ''));
    if (!isBinding || delta === 0) continue;
    // bake the (quantization) node transform → plain float geometry in asset coordinates, parented to the asset root
    const geo = bakeFloat(m.geometry, new THREE.Matrix4().multiplyMatrices(toSrc, m.matrixWorld));
    const idx = geo.index!, pos = geo.getAttribute('position');
    const front: number[] = [], back: number[] = [];
    for (let t = 0; t < idx.count; t += 3) {
      const cx = pos.getX(idx.getX(t)) + pos.getX(idx.getX(t + 1)) + pos.getX(idx.getX(t + 2));
      (cx > 0 ? back : front).push(idx.getX(t), idx.getX(t + 1), idx.getX(t + 2)); // asset +x = tail after the 180° turn
    }
    const a = geo.clone(); a.setIndex(front);
    const r = geo.clone(); r.setIndex(back);
    // back binding centre in asset coords (highback at z ≈ +0.14, toe strap at z ≈ −0.08)
    const pivot = new THREE.Vector3(BOARD_ASSET.stanceHalf, 0, 0.03);
    r.translate(-pivot.x, 0, -pivot.z).rotateY(delta).translate(pivot.x, 0, pivot.z);
    m.removeFromParent();
    for (const gg of [a, r]) {
      const mm = new THREE.Mesh(gg, m.material);
      mm.name = m.name; mm.castShadow = true; mm.receiveShadow = true;
      src.add(mm);
    }
  }
  src.rotation.y = Math.PI; // toe edge → +z
  return g;
}

function bakeFloat(src: THREE.BufferGeometry, m: THREE.Matrix4): THREE.BufferGeometry {
  const g = new THREE.BufferGeometry();
  for (const name of Object.keys(src.attributes)) {
    const a = src.getAttribute(name) as THREE.BufferAttribute;
    const out = new Float32Array(a.count * a.itemSize);
    for (let i = 0; i < a.count; i++) for (let k = 0; k < a.itemSize; k++) out[i * a.itemSize + k] = a.getComponent(i, k);
    g.setAttribute(name, new THREE.BufferAttribute(out, a.itemSize));
  }
  g.setIndex(src.index ? Array.from(src.index.array as ArrayLike<number>) : null);
  g.applyMatrix4(m);
  return g;
}

let decoderReady: Promise<void> | null = null;
/** Load Manny + board (meshopt-compressed glTF). `onProgress` gets 0..1 over both files. */
export async function loadMannyAssets(base: string, onProgress?: (f: number) => void): Promise<MannyAssets> {
  decoderReady ??= MeshoptDecoder.ready;
  await decoderReady;
  const loader = new GLTFLoader();
  loader.setMeshoptDecoder(MeshoptDecoder);
  const files = ['manny.glb', 'snowboard.glb'];
  const done = [0, 0], total = [360_000, 150_000]; // fallback sizes when Content-Length is missing
  const report = () => onProgress?.(Math.min(1, (done[0] + done[1]) / (total[0] + total[1])));
  const [m, b] = await Promise.all(files.map((f, i) => loader.loadAsync(`${base}${f}`, (e) => {
    if (e.lengthComputable && e.total > 0) total[i] = e.total;
    done[i] = e.loaded; report();
  })));
  onProgress?.(1);
  return { manny: m.scene, board: b.scene };
}

/** Asset URL base (vite `base` aware). */
export function riderAssetBase(): string {
  const base = (import.meta as unknown as { env?: { BASE_URL?: string } }).env?.BASE_URL ?? '/';
  return `${base}assets/rider/`;
}
